/**
 * Pikchr Recursive Descent Parser
 * 
 * Parses tokens generated by Lexer into typed AST nodes.
 * Implements comprehensive parsing for single statements and full scripts,
 * covering shapes, complex expressions, object references, and all Pikchr attributes.
 */

import { Lexer, Token, TokenType, SHAPE_KEYWORDS, DIRECTION_KEYWORDS, COLOR_KEYWORDS } from './lexer';
import {
  StatementNode,
  ProgramNode,
  ShapeStatementNode,
  BlockStatementNode,
  AssignmentStatementNode,
  DirectionStatementNode,
  DefineStatementNode,
  PrintStatementNode,
  MacroCallStatementNode,
  EmptyStatementNode,
  AttributeNode,
  TextAttributeNode,
  DimensionAttributeNode,
  SameAttributeNode,
  FitAttributeNode,
  StyleAttributeNode,
  BehindAttributeNode,
  DirectionAttributeNode,
  PositionAttributeNode,
  WaypointAttributeNode,
  ArcAttributeNode,
  ExpressionNode,
  NumberLiteralNode,
  StringLiteralNode,
  ColorLiteralNode,
  VariableReferenceNode,
  ObjectReferenceNode,
  BinaryExpressionNode,
  UnaryExpressionNode,
  GroupExpressionNode,
  FunctionCallNode,
  CoordinatePairNode,
  BetweenExpressionNode,
  HeadingExpressionNode,
  ParseError,
  ParseResult,
  SourcePosition,
  SourceLocation,
} from './types';

export class Parser {
  private tokens: Token[];
  private current = 0;

  constructor(tokens: Token[]) {
    this.tokens = tokens;
  }

  public static parse(source: string): ParseResult<ProgramNode> {
    try {
      const lexer = new Lexer(source);
      const tokens = lexer.tokenize();
      const parser = new Parser(tokens);
      const program = parser.parseProgram();
      return { success: true, ast: program };
    } catch (err: any) {
      if (err && typeof err === 'object' && 'line' in err) {
        return { success: false, error: err as ParseError };
      }
      return {
        success: false,
        error: {
          message: err?.message || 'Syntax error',
          line: 1,
          column: 1,
          offset: 0,
        },
      };
    }
  }

  public static parseStatement(statementText: string): ParseResult<StatementNode> {
    try {
      const lexer = new Lexer(statementText);
      const tokens = lexer.tokenize();
      const parser = new Parser(tokens);
      
      // Skip leading newlines / semicolons
      parser.skipTerminators();
      if (parser.isAtEnd()) {
        const emptyNode: EmptyStatementNode = { type: 'EmptyStatement' };
        return { success: true, ast: emptyNode };
      }

      const stmt = parser.parseStatement();
      parser.skipTerminators();

      if (!parser.isAtEnd()) {
        const extraToken = parser.peek();
        throw parser.error(`Unexpected token '${extraToken.value}' after statement`, extraToken);
      }

      return { success: true, ast: stmt };
    } catch (err: any) {
      if (err && typeof err === 'object' && 'line' in err) {
        return { success: false, error: err as ParseError };
      }
      return {
        success: false,
        error: {
          message: err?.message || 'Syntax error',
          line: 1,
          column: 1,
          offset: 0,
        },
      };
    }
  }

  // ----------------------------------------------------
  // Program & Statement Rules
  // ----------------------------------------------------

  public parseProgram(): ProgramNode {
    const statements: StatementNode[] = [];
    const startLoc = this.getPos();

    while (!this.isAtEnd()) {
      this.skipTerminators();
      if (this.isAtEnd()) break;

      const stmt = this.parseStatement();
      if (stmt.type !== 'EmptyStatement') {
        statements.push(stmt);
      }
      this.skipTerminators();
    }

    return {
      type: 'Program',
      statements,
      loc: { start: startLoc, end: this.getPos() },
    };
  }

  public parseStatement(): StatementNode {
    const startLoc = this.getPos();

    // 1. Label definition at the beginning: e.g. "In:", "CP:", "Start:"
    let label: string | undefined = undefined;
    if (this.check('LABEL_DEF')) {
      const labelToken = this.advance();
      label = labelToken.value;
    }

    // Empty statement check
    if (this.check('SEMICOLON') || this.check('NEWLINE') || this.isAtEnd()) {
      if (label) {
        // Label only statement (acts as a reference point)
        return {
          type: 'ShapeStatement',
          label,
          shapeType: 'move',
          attributes: [],
          loc: { start: startLoc, end: this.getPos() },
        };
      }
      return { type: 'EmptyStatement', loc: { start: startLoc, end: this.getPos() } };
    }

    // 2. Define macro statement: "define name { ... }"
    if (this.matchKeyword('define')) {
      return this.parseDefineStatement(startLoc);
    }

    // 3. Print or Assert statement: "print expr", "assert expr"
    if (this.matchKeyword('print') || this.matchKeyword('assert')) {
      const kind = this.previous().value as 'print' | 'assert';
      return this.parsePrintStatement(kind, startLoc);
    }

    // 4. Sub-diagram block statement: "[ ... ]"
    if (this.checkPunctuation('[')) {
      return this.parseBlockStatement(label, startLoc);
    }

    // 5. Arrow shorthand: "->", "<-", "<->"
    if (this.check('ARROW')) {
      const arrowHead = this.advance().value;
      const attributes = this.parseAttributes();
      attributes.unshift({
        type: 'ArcAttribute',
        property: 'arrow_head',
        value: arrowHead,
      });
      return {
        type: 'ShapeStatement',
        label,
        shapeType: 'arrow',
        attributes,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 6. Shape declaration: "box", "circle", "line", "arrow", etc.
    if (this.check('SHAPE')) {
      const shapeType = this.advance().value;
      const attributes = this.parseAttributes();
      return {
        type: 'ShapeStatement',
        label,
        shapeType,
        attributes,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 7. Standalone Text: starts with a string literal without a shape keyword
    // e.g. "trunk" below at 2nd last box.s
    if (this.check('STRING')) {
      const attributes = this.parseAttributes();
      return {
        type: 'ShapeStatement',
        label,
        shapeType: 'text',
        attributes,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 8. Direction statement or Direction-first command (e.g. "down", "right", "arrow down 1.25")
    if (this.check('DIRECTION')) {
      const dir = this.advance().value as 'right' | 'down' | 'left' | 'up' | 'heading';
      let distance: ExpressionNode | undefined = undefined;

      // Check if distance or shape follows
      if (this.isExpressionStart() && !this.checkTerminator()) {
        distance = this.parseExpression();
      }

      return {
        type: 'DirectionStatement',
        direction: dir,
        distance,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 9. Variable assignment: e.g. "lineht *= 0.4", "$margin = lineht*2.5", "scale = 0.75"
    if (this.check('IDENTIFIER') || this.check('KEYWORD')) {
      const nextToken = this.peek(1);
      if (
        nextToken.type === 'OPERATOR' &&
        ['=', '+=', '-=', '*=', '/='].includes(nextToken.value)
      ) {
        const varName = this.advance().value;
        const op = this.advance().value as '=' | '+=' | '-=' | '*=' | '/=';
        const expr = this.parseExpression();
        return {
          type: 'AssignmentStatement',
          variable: varName,
          operator: op,
          expression: expr,
          loc: { start: startLoc, end: this.getPos() },
        };
      }
    }

    // 10. Position assignment to Label: e.g. "Paper: CRT + 1.05, 0.75" or "X0: last.e + (0.3,0)"
    if (label && this.isExpressionStart()) {
      const expr = this.parseExpression();
      return {
        type: 'AssignmentStatement',
        variable: label,
        operator: '=',
        expression: expr,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 11. Macro invocation (standalone identifier without operator): e.g. "ndblock"
    if (this.check('IDENTIFIER')) {
      const macroName = this.advance().value;
      return {
        type: 'MacroCallStatement',
        name: macroName,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // If none matched, report error
    const unexpected = this.peek();
    throw this.error(`Unexpected statement starting with '${unexpected.value}'`, unexpected);
  }

  // ----------------------------------------------------
  // Special Statement Parsers
  // ----------------------------------------------------

  private parseDefineStatement(startLoc: SourcePosition): DefineStatementNode {
    if (!this.check('IDENTIFIER') && !this.check('KEYWORD')) {
      throw this.error('Expected macro name after define');
    }
    const name = this.advance().value;

    if (!this.matchPunctuation('{')) {
      throw this.error("Expected '{' starting define macro body");
    }

    const body: StatementNode[] = [];
    let rawBody = '';
    while (!this.checkPunctuation('}') && !this.isAtEnd()) {
      this.skipTerminators();
      if (this.checkPunctuation('}') || this.isAtEnd()) break;
      const stmt = this.parseStatement();
      if (stmt.type !== 'EmptyStatement') {
        body.push(stmt);
      }
      this.skipTerminators();
    }

    if (!this.matchPunctuation('}')) {
      throw this.error("Expected '}' closing define macro body");
    }

    return {
      type: 'DefineStatement',
      name,
      body,
      rawBody,
      loc: { start: startLoc, end: this.getPos() },
    };
  }

  private parsePrintStatement(kind: 'print' | 'assert', startLoc: SourcePosition): PrintStatementNode {
    const args: ExpressionNode[] = [];
    while (!this.checkTerminator() && !this.isAtEnd()) {
      args.push(this.parseExpression());
      if (this.matchPunctuation(',')) {
        continue;
      } else {
        break;
      }
    }
    return {
      type: 'PrintStatement',
      kind,
      args,
      loc: { start: startLoc, end: this.getPos() },
    };
  }

  private parseBlockStatement(label: string | undefined, startLoc: SourcePosition): BlockStatementNode {
    this.consumePunctuation('[', "Expected '[' to open block statement");
    const body: StatementNode[] = [];

    while (!this.checkPunctuation(']') && !this.isAtEnd()) {
      this.skipTerminators();
      if (this.checkPunctuation(']') || this.isAtEnd()) break;
      const stmt = this.parseStatement();
      if (stmt.type !== 'EmptyStatement') {
        body.push(stmt);
      }
      this.skipTerminators();
    }

    this.consumePunctuation(']', "Expected ']' to close block statement");
    const attributes = this.parseAttributes();

    return {
      type: 'BlockStatement',
      label,
      body,
      attributes,
      loc: { start: startLoc, end: this.getPos() },
    };
  }

  // ----------------------------------------------------
  // Attribute Parsers
  // ----------------------------------------------------

  private parseAttributes(): AttributeNode[] {
    const attributes: AttributeNode[] = [];

    while (!this.checkTerminator() && !this.isAtEnd()) {
      const attr = this.parseSingleAttribute();
      if (attr) {
        attributes.push(attr);
      } else {
        break;
      }
    }

    return attributes;
  }

  private parseSingleAttribute(): AttributeNode | null {
    const startLoc = this.getPos();

    // 1. Text String literal: "Text" [modifiers...]
    if (this.check('STRING')) {
      const text = this.advance().value;
      const modifiers: string[] = [];
      while (
        this.checkAnyKeyword([
          'big', 'small', 'bold', 'italic', 'mono',
          'aligned', 'above', 'below', 'center', 'ljust', 'rjust'
        ])
      ) {
        modifiers.push(this.advance().value);
      }
      return {
        type: 'TextAttribute',
        text,
        modifiers,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 2. Arrow Heads: "->", "<-", "<->", "none"
    if (this.check('ARROW') || (this.check('KEYWORD') && this.peek().value === 'none')) {
      const val = this.advance().value;
      return {
        type: 'ArcAttribute',
        property: 'arrow_head',
        value: val,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 3. Arc Directions: "cw", "ccw"
    if (this.matchKeyword('cw') || this.matchKeyword('ccw')) {
      return {
        type: 'ArcAttribute',
        property: this.previous().value as 'cw' | 'ccw',
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 4. Dimensions: wid, ht, rad, diam, thickness
    if (this.matchAnyKeyword(['width', 'wid', 'height', 'ht', 'radius', 'rad', 'diameter', 'diam', 'thickness'])) {
      const rawName = this.previous().value;
      let name: 'width' | 'height' | 'radius' | 'diameter' | 'thickness';
      if (rawName === 'width' || rawName === 'wid') name = 'width';
      else if (rawName === 'height' || rawName === 'ht') name = 'height';
      else if (rawName === 'radius' || rawName === 'rad') name = 'radius';
      else if (rawName === 'diameter' || rawName === 'diam') name = 'diameter';
      else name = 'thickness';

      const value = this.parseExpression();
      return {
        type: 'DimensionAttribute',
        name,
        rawName,
        value,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 5. "same" [as target]
    if (this.matchKeyword('same')) {
      let asTarget: ObjectReferenceNode | undefined = undefined;
      if (this.matchKeyword('as')) {
        asTarget = this.parseObjectReference();
      }
      return {
        type: 'SameAttribute',
        asTarget,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 6. "fit"
    if (this.matchKeyword('fit')) {
      return {
        type: 'FitAttribute',
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 7. Styles: fill, color, dashed, dotted, thin, invis
    if (this.matchKeyword('fill') || this.matchKeyword('color')) {
      const property = this.previous().value as 'fill' | 'color';
      const value = this.parseExpression();
      return {
        type: 'StyleAttribute',
        property,
        value,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    if (this.matchKeyword('dashed') || this.matchKeyword('dotted')) {
      const property = this.previous().value as 'dashed' | 'dotted';
      let value: ExpressionNode | undefined = undefined;
      if (this.isExpressionStart() && !this.checkTerminator() && !this.isAttributeStart()) {
        value = this.parseExpression();
      }
      return {
        type: 'StyleAttribute',
        property,
        value,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    if (this.matchKeyword('thin') || this.matchKeyword('thick') || this.matchKeyword('invis')) {
      const property = this.previous().value as 'thin' | 'thick' | 'invis';
      if (property === 'thick' && this.isDistanceStart() && !this.checkTerminator() && !this.isAttributeStart()) {
        const value = this.parseExpression();
        return {
          type: 'DimensionAttribute',
          name: 'thickness',
          rawName: 'thick',
          value,
          loc: { start: startLoc, end: this.getPos() },
        };
      }
      return {
        type: 'StyleAttribute',
        property,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 8. "behind Target"
    if (this.matchKeyword('behind')) {
      const target = this.parseObjectReference();
      return {
        type: 'BehindAttribute',
        target,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 9. Direction & distance: "right", "down", "left", "up", "heading"
    if (this.check('DIRECTION')) {
      const dir = this.advance().value as 'right' | 'down' | 'left' | 'up' | 'heading';
      let distance: ExpressionNode | undefined = undefined;
      if (this.isDistanceStart() && !this.checkTerminator() && !this.isAttributeStart()) {
        distance = this.parseExpression();
      }
      return {
        type: 'DirectionAttribute',
        direction: dir,
        distance,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 10. Linear distance without direction (e.g. "arrow 50%", "arrow 200%", "arrow 0.8in", "move lineht")
    if (this.isDistanceStart() && !this.checkTerminator() && !this.isAttributeStart()) {
      const distance = this.parseExpression();
      return {
        type: 'DirectionAttribute',
        direction: 'right',
        distance,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 11. Positions: "at", "from", "to", "go", "chop", "with ... at"
    if (this.matchKeyword('at') || this.matchKeyword('from') || this.matchKeyword('to')) {
      const kind = this.previous().value as 'at' | 'from' | 'to';
      const position = this.parseExpression();
      return {
        type: 'PositionAttribute',
        kind,
        position,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    if (this.matchKeyword('chop')) {
      let distance: ExpressionNode | undefined = undefined;
      if (this.isDistanceStart() && !this.checkTerminator() && !this.isAttributeStart()) {
        distance = this.parseExpression();
      }
      return {
        type: 'PositionAttribute',
        kind: 'chop',
        distance,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    if (this.matchKeyword('go')) {
      let direction: 'right' | 'down' | 'left' | 'up' | undefined = undefined;
      if (this.check('DIRECTION')) {
        direction = this.advance().value as any;
      }
      let distance: ExpressionNode | undefined = undefined;
      if (this.isDistanceStart() && !this.checkTerminator() && !this.isAttributeStart()) {
        distance = this.parseExpression();
      }
      return {
        type: 'PositionAttribute',
        kind: 'go',
        direction,
        distance,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // "with .anchor at Position" or "with Anchor at Position"
    if (this.matchKeyword('with')) {
      let anchor = '';
      if (this.matchPunctuation('.')) {
        anchor = '.' + this.advance().value;
      } else {
        anchor = this.advance().value;
      }

      this.consumeKeyword('at', "Expected 'at' following with <anchor>");
      const position = this.parseExpression();
      return {
        type: 'PositionAttribute',
        kind: 'with_at',
        anchor,
        position,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // "until [even with] Position"
    if (this.matchKeyword('until')) {
      this.matchKeyword('even');
      this.matchKeyword('with');
      const position = this.parseExpression();
      return {
        type: 'PositionAttribute',
        kind: 'until_even_with',
        position,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // 12. Waypoint: "then [direction dist] [until even with ...] [to position] [rad r]"
    if (this.matchKeyword('then')) {
      let direction: 'right' | 'down' | 'left' | 'up' | undefined = undefined;
      let distance: ExpressionNode | undefined = undefined;
      let untilEvenWith: ExpressionNode | undefined = undefined;
      let to: ExpressionNode | undefined = undefined;
      let radius: ExpressionNode | undefined = undefined;

      while (!this.checkTerminator() && !(this.check('KEYWORD') && this.peek().value === 'then') && !this.isAtEnd()) {
        if (this.check('DIRECTION')) {
          direction = this.advance().value as any;
          if (this.isDistanceStart() && !this.checkTerminator() && !this.isAttributeStart()) {
            distance = this.parseExpression();
          }
        } else if (this.matchKeyword('until')) {
          this.matchKeyword('even');
          this.matchKeyword('with');
          untilEvenWith = this.parseExpression();
        } else if (this.matchKeyword('to')) {
          to = this.parseExpression();
        } else if (this.matchKeyword('rad') || this.matchKeyword('radius')) {
          radius = this.parseExpression();
        } else if (this.isDistanceStart() && !this.isAttributeStart() && !this.checkTerminator()) {
          const extra = this.parseExpression();
          if (!distance) distance = extra;
        } else {
          break;
        }
      }

      return {
        type: 'WaypointAttribute',
        direction,
        distance,
        untilEvenWith,
        to,
        radius,
        loc: { start: startLoc, end: this.getPos() },
      };
    }

    // No attribute recognized
    return null;
  }

  private isAttributeStart(): boolean {
    if (this.check('STRING') || this.check('ARROW')) return true;
    if (this.check('DIRECTION')) return true;
    if (this.check('KEYWORD')) {
      const val = this.peek().value;
      return [
        'width', 'wid', 'height', 'ht', 'radius', 'rad', 'diameter', 'diam', 'thickness', 'thick',
        'same', 'as', 'fit', 'fill', 'color', 'dashed', 'dotted', 'thin', 'thick', 'invis', 'behind',
        'at', 'from', 'to', 'with', 'go', 'chop', 'then', 'until', 'cw', 'ccw',
        'big', 'small', 'bold', 'italic', 'mono', 'aligned', 'above', 'below', 'center', 'ljust', 'rjust'
      ].includes(val);
    }
    return false;
  }

  // ----------------------------------------------------
  // Expression Parser (Operator Precedence)
  // ----------------------------------------------------

  public parseExpression(): ExpressionNode {
    return this.parseCommaPair();
  }

  private parseCommaPair(): ExpressionNode {
    let expr = this.parseRelativePosition();
    if (this.matchPunctuation(',')) {
      const right = this.parseRelativePosition();
      return {
        type: 'CoordinatePair',
        x: expr,
        y: right,
      };
    }
    return expr;
  }

  private parseRelativePosition(): ExpressionNode {
    let expr = this.parseLogicalOr();

    // Check if followed by Direction [of] Target
    // e.g. "1.25*$margin east of 1st box.e" or "lineht below Lemon.s"
    while (
      (this.checkAnyKeyword([
        'right', 'down', 'left', 'up', 'heading',
        'north', 'south', 'east', 'west', 'ne', 'nw', 'se', 'sw'
      ]) && this.peek(1).value === 'of') ||
      (this.checkAnyKeyword(['above', 'below']) && (this.peek(1).value === 'of' || this.isObjectReferenceStartAt(1)))
    ) {
      const dir = this.advance().value;
      this.matchKeyword('of');
      const target = this.parseLogicalOr();
      expr = {
        type: 'HeadingExpression',
        distance: expr,
        angle: { type: 'StringLiteral', value: dir },
        origin: target,
      };
    }

    return expr;
  }

  private isObjectReferenceStartAt(offset: number): boolean {
    const token = this.peek(offset);
    if (!token || token.type === 'EOF') return false;
    if (token.type === 'ORDINAL') return true;
    if (token.type === 'IDENTIFIER') return true;
    if (token.type === 'SHAPE') return true;
    if (token.type === 'KEYWORD') {
      return ['previous', 'last', 'first', 'start', 'end', 'top', 'bottom', 'bot', 'box', 'circle', 'line', 'arrow'].includes(token.value);
    }
    return false;
  }

  private parseLogicalOr(): ExpressionNode {
    let expr = this.parseLogicalAnd();
    while (this.matchOperator('||')) {
      const operator = this.previous().value as any;
      const right = this.parseLogicalAnd();
      expr = { type: 'BinaryExpression', operator, left: expr, right };
    }
    return expr;
  }

  private parseLogicalAnd(): ExpressionNode {
    let expr = this.parseEquality();
    while (this.matchOperator('&&')) {
      const operator = this.previous().value as any;
      const right = this.parseEquality();
      expr = { type: 'BinaryExpression', operator, left: expr, right };
    }
    return expr;
  }

  private parseEquality(): ExpressionNode {
    let expr = this.parseRelational();
    while (this.matchOperator('==') || this.matchOperator('!=')) {
      const operator = this.previous().value as any;
      const right = this.parseRelational();
      expr = { type: 'BinaryExpression', operator, left: expr, right };
    }
    return expr;
  }

  private parseRelational(): ExpressionNode {
    let expr = this.parseAdditive();
    while (
      this.matchOperator('<') || this.matchOperator('<=') ||
      this.matchOperator('>') || this.matchOperator('>=')
    ) {
      const operator = this.previous().value as any;
      const right = this.parseAdditive();
      expr = { type: 'BinaryExpression', operator, left: expr, right };
    }
    return expr;
  }

  private parseAdditive(): ExpressionNode {
    let expr = this.parseMultiplicative();
    while (this.matchOperator('+') || this.matchOperator('-')) {
      const operator = this.previous().value as '+' | '-';
      const right = this.parseMultiplicative();
      expr = { type: 'BinaryExpression', operator, left: expr, right };
    }
    return expr;
  }

  private parseMultiplicative(): ExpressionNode {
    let expr = this.parseUnary();
    while (this.matchOperator('*') || this.matchOperator('/') || this.matchOperator('%')) {
      const operator = this.previous().value as '*' | '/' | '%';
      const right = this.parseUnary();
      expr = { type: 'BinaryExpression', operator, left: expr, right };
    }
    return expr;
  }

  private parseUnary(): ExpressionNode {
    if (this.matchOperator('-') || this.matchOperator('+') || this.matchOperator('!')) {
      const operator = this.previous().value as '+' | '-' | '!';
      const argument = this.parseUnary();
      return { type: 'UnaryExpression', operator, argument };
    }
    return this.parsePrimary();
  }

  private parsePrimary(): ExpressionNode {
    // 1. Natural language position prefix: "Nth vertex of ...", "top of ...", "bottom of ..."
    if (this.check('ORDINAL') && this.peek(1).value === 'vertex') {
      const ordStr = this.advance().value;
      this.advance(); // consume "vertex"
      this.consumeKeyword('of', "Expected 'of' after vertex");
      const target = this.parseObjectReference();
      const vertexIdx = parseInt(ordStr, 10) || 1;
      return {
        type: 'ObjectReference',
        raw: `${ordStr} vertex of ${target.raw}`,
        vertexIndex: vertexIdx,
        subObject: target,
      };
    }

    if (
      this.matchAnyKeyword([
        'top', 'bottom', 'bot', 'left', 'right',
        'east', 'west', 'north', 'south', 'ne', 'nw', 'se', 'sw',
        'end', 'start', 'above', 'below'
      ])
    ) {
      const anchorName = this.previous().value;
      if (this.matchKeyword('of')) {
        const target = this.parseObjectReference();
        return {
          type: 'ObjectReference',
          raw: `${anchorName} of ${target.raw}`,
          name: target.name,
          anchor: anchorName,
          subObject: target,
        };
      }
    }

    // 2. Number Literal
    if (this.check('NUMBER')) {
      const numToken = this.advance();
      let expr: ExpressionNode = {
        type: 'NumberLiteral',
        value: parseFloat(numToken.value),
        unit: numToken.unit as any,
        raw: numToken.value + (numToken.unit || ''),
      };

      // Check for interpolation fraction: "1/4<Tokenizer.sw, Tokenizer.nw>"
      if (this.matchOperator('/')) {
        const denomToken = this.advance();
        const denomVal = parseFloat(denomToken.value);
        const fractionNode: ExpressionNode = {
          type: 'BinaryExpression',
          operator: '/',
          left: expr,
          right: {
            type: 'NumberLiteral',
            value: denomVal,
            raw: denomToken.value,
          },
        };

        if (this.matchOperator('<')) {
          const fromPos = this.parseAdditive();
          this.consumePunctuation(',', "Expected ',' between interpolation targets");
          const toPos = this.parseAdditive();
          this.consumeOperator('>', "Expected '>' closing interpolation target");
          return {
            type: 'BetweenExpression',
            fraction: fractionNode,
            from: fromPos,
            to: toPos,
          };
        } else if (this.matchKeyword('way') || this.matchKeyword('between')) {
          if (this.previous().value === 'way') {
            this.matchKeyword('between');
          }
          const fromPos = this.parseAdditive();
          this.consumeKeyword('and', "Expected 'and' in between expression");
          const toPos = this.parseAdditive();
          return {
            type: 'BetweenExpression',
            fraction: fractionNode,
            from: fromPos,
            to: toPos,
          };
        }
        expr = fractionNode;
      }

      return expr;
    }

    // 4. Hex Color or Named Color
    if (this.check('HEX_COLOR')) {
      const hex = this.advance().value;
      return { type: 'ColorLiteral', value: hex, isHex: true };
    }

    if (
      (this.check('KEYWORD') && COLOR_KEYWORDS.has(this.peek().value)) ||
      (this.check('IDENTIFIER') && COLOR_KEYWORDS.has(this.peek().value.toLowerCase()))
    ) {
      const colorVal = this.advance().value;
      return { type: 'ColorLiteral', value: colorVal, isHex: false };
    }

    // 5. String literal
    if (this.check('STRING')) {
      const str = this.advance().value;
      return { type: 'StringLiteral', value: str };
    }

    // 6. Group or Coordinate Pair: "(x, y)" or "(expr)"
    if (this.matchPunctuation('(')) {
      const first = this.parseExpression();
      if (this.matchPunctuation(',')) {
        const second = this.parseExpression();
        this.consumePunctuation(')', "Expected ')' closing coordinate pair");
        return { type: 'CoordinatePair', x: first, y: second };
      }
      this.consumePunctuation(')', "Expected ')' closing grouped expression");
      return { type: 'GroupExpression', expression: first };
    }

    // 7. Function Call: "dist(A, B)", "sqrt(x)", "abs(x)"
    if (this.check('IDENTIFIER') && this.peek(1).value === '(') {
      const fnName = this.advance().value;
      this.advance(); // consume '('
      const args: ExpressionNode[] = [];
      while (!this.checkPunctuation(')') && !this.isAtEnd()) {
        args.push(this.parseExpression());
        if (!this.matchPunctuation(',')) break;
      }
      this.consumePunctuation(')', "Expected ')' closing function call");

      // Check if followed by "heading angle from origin"
      if (this.matchKeyword('heading')) {
        const angle = this.parseExpression();
        this.consumeKeyword('from', "Expected 'from' in heading expression");
        const origin = this.parseExpression();
        return {
          type: 'HeadingExpression',
          distance: { type: 'FunctionCall', name: fnName, args },
          angle,
          origin,
        };
      }

      return { type: 'FunctionCall', name: fnName, args };
    }

    // 8. Object Reference or Variable Reference: e.g. "In.n.y", "1st box.e", "$margin", "previous.w"
    if (this.isObjectReferenceStart()) {
      return this.parseObjectReference();
    }

    const unexpected = this.peek();
    throw this.error(`Unexpected token '${unexpected.value}' in expression`, unexpected);
  }

  private isObjectReferenceStart(): boolean {
    if (this.check('ORDINAL')) return true;
    if (this.check('IDENTIFIER')) return true;
    if (this.check('KEYWORD')) {
      const val = this.peek().value;
      return ['previous', 'last', 'first', 'box', 'circle', 'line', 'arrow'].includes(val);
    }
    return false;
  }

  private parseObjectReference(): ObjectReferenceNode {
    let raw = '';
    let ordinal: string | undefined = undefined;
    let qualifier: string | undefined = undefined;
    let name: string | undefined = undefined;
    let anchor: string | undefined = undefined;
    let component: 'x' | 'y' | undefined = undefined;

    // Check ordinal: e.g. "1st", "2nd", "last", "first", "previous"
    if (this.check('ORDINAL') || this.checkAnyKeyword(['first', 'last', 'previous'])) {
      ordinal = this.advance().value;
      raw += ordinal;

      // May be followed by secondary ordinal: e.g. "2nd last box.s"
      if (this.checkAnyKeyword(['last', 'previous'])) {
        ordinal += ' ' + this.advance().value;
        raw += ' ' + ordinal;
      }

      // May be followed by shape qualifier: e.g. "1st box"
      if (this.check('SHAPE') || this.checkAnyKeyword(['box', 'circle', 'line', 'arrow', 'oval', 'ellipse'])) {
        qualifier = this.advance().value;
        raw += ' ' + qualifier;
      }
    } else if (this.check('SHAPE')) {
      qualifier = this.advance().value;
      raw += qualifier;
    } else {
      name = this.advance().value;
      raw += name;
    }

    // Check dot accessors: .anchor, .x, .y, .subObject
    while (this.matchPunctuation('.')) {
      raw += '.';
      const part = this.advance().value;
      raw += part;

      if (part === 'x' || part === 'y') {
        component = part;
      } else {
        anchor = part;
      }
    }

    return {
      type: 'ObjectReference',
      raw,
      name,
      ordinal,
      qualifier,
      anchor,
      component,
    };
  }

  // ----------------------------------------------------
  // Helper / Utility Methods
  // ----------------------------------------------------

  private isDistanceStart(): boolean {
    if (this.check('NUMBER') || this.check('ORDINAL')) return true;
    if (this.check('IDENTIFIER') && !COLOR_KEYWORDS.has(this.peek().value.toLowerCase())) return true;
    if (this.checkPunctuation('(')) return true;
    if (this.checkOperator('-') || this.checkOperator('+')) return true;
    if (this.checkAnyKeyword(['first', 'last', 'previous'])) return true;
    return false;
  }

  private isExpressionStart(): boolean {
    if (this.check('NUMBER') || this.check('HEX_COLOR') || this.check('STRING')) return true;
    if (this.check('IDENTIFIER') || this.check('ORDINAL')) return true;
    if (this.checkPunctuation('(')) return true;
    if (this.checkOperator('-') || this.checkOperator('+') || this.checkOperator('!')) return true;
    if (this.checkAnyKeyword(['first', 'last', 'previous', 'top', 'bottom', 'bot', 'left', 'right', 'dist'])) return true;
    return false;
  }

  private skipTerminators(): void {
    while (this.check('SEMICOLON') || this.check('NEWLINE')) {
      this.advance();
    }
  }

  private checkTerminator(): boolean {
    return this.check('SEMICOLON') || this.check('NEWLINE') || this.check('EOF') || this.checkPunctuation(']') || this.checkPunctuation('}');
  }

  private check(type: TokenType): boolean {
    if (this.isAtEnd()) return type === 'EOF';
    return this.peek().type === type;
  }

  private checkPunctuation(char: string): boolean {
    if (this.isAtEnd()) return false;
    const token = this.peek();
    return token.type === 'PUNCTUATION' && token.value === char;
  }

  private checkOperator(op: string): boolean {
    if (this.isAtEnd()) return false;
    const token = this.peek();
    return token.type === 'OPERATOR' && token.value === op;
  }

  private checkAnyKeyword(words: string[]): boolean {
    if (this.isAtEnd()) return false;
    const token = this.peek();
    return (token.type === 'KEYWORD' || token.type === 'SHAPE' || token.type === 'DIRECTION') && words.includes(token.value);
  }

  private matchKeyword(word: string): boolean {
    if (this.isAtEnd()) return false;
    const token = this.peek();
    if ((token.type === 'KEYWORD' || token.type === 'SHAPE' || token.type === 'DIRECTION') && token.value === word) {
      this.advance();
      return true;
    }
    return false;
  }

  private matchAnyKeyword(words: string[]): boolean {
    if (this.isAtEnd()) return false;
    const token = this.peek();
    if ((token.type === 'KEYWORD' || token.type === 'SHAPE' || token.type === 'DIRECTION') && words.includes(token.value)) {
      this.advance();
      return true;
    }
    return false;
  }

  private matchOperator(op: string): boolean {
    if (this.isAtEnd()) return false;
    const token = this.peek();
    if (token.type === 'OPERATOR' && token.value === op) {
      this.advance();
      return true;
    }
    return false;
  }

  private matchPunctuation(char: string): boolean {
    if (this.isAtEnd()) return false;
    const token = this.peek();
    if (token.type === 'PUNCTUATION' && token.value === char) {
      this.advance();
      return true;
    }
    return false;
  }

  private consumePunctuation(char: string, message: string): Token {
    if (this.checkPunctuation(char)) return this.advance();
    throw this.error(message);
  }

  private consumeOperator(op: string, message: string): Token {
    if (this.checkOperator(op)) return this.advance();
    throw this.error(message);
  }

  private consumeKeyword(word: string, message: string): Token {
    if (this.matchKeyword(word)) return this.previous();
    throw this.error(message);
  }

  private advance(): Token {
    if (!this.isAtEnd()) this.current++;
    return this.previous();
  }

  private isAtEnd(): boolean {
    return this.current >= this.tokens.length || this.peek().type === 'EOF';
  }

  private peek(offset = 0): Token {
    const idx = Math.min(this.current + offset, this.tokens.length - 1);
    return this.tokens[idx];
  }

  private previous(): Token {
    return this.tokens[this.current - 1];
  }

  private getPos(): SourcePosition {
    const token = this.peek();
    return { line: token.line, column: token.column, offset: token.offset };
  }

  private error(message: string, token: Token = this.peek()): ParseError {
    return {
      message,
      line: token.line,
      column: token.column,
      offset: token.offset,
      unexpectedToken: token.value,
    };
  }
}
